"use client";
// Blur Hover Reveal: monochrome marks rest at reduced opacity. Hovering one brings it into
// focus while the others soften and recede, like a depth-of-field pull.

import * as React from "react";
import { motion, useReducedMotion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup, type Logo } from "./logos";

const SPRING = { type: "spring" as const, stiffness: 420, damping: 34 };
const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

export type LogoCloudBlurProps = {
  /** Headline above the grid. */
  title?: string;
  /** Line under the headline. Empty string hides it. */
  subtitle?: string;
  /** Marks in the grid. Defaults to the twelve placeholder lockups. */
  logos?: Logo[];
  /** How many marks to show (1–24). Defaults to every logo passed. */
  count?: number;
  /** Opacity of every mark while nothing is hovered (0.1–1). */
  restOpacity?: number;
  /** Opacity of the other marks while one is hovered (0–1). */
  recedeOpacity?: number;
  /** Blur in px on the other marks while one is hovered (0–8). */
  recedeBlur?: number;
  /** Scale of the hovered mark (1–1.3). */
  hoverScale?: number;
  className?: string;
};

function clamp(value: number | undefined, min: number, max: number, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

export default function LogoCloudBlur({
  title = "The teams behind the products you open every morning.",
  subtitle = "Hover a name to bring it into focus.",
  logos = LOGOS,
  count,
  restOpacity = 0.5,
  recedeOpacity = 0.2,
  recedeBlur = 2,
  hoverScale = 1.06,
  className,
}: LogoCloudBlurProps) {
  const [hovered, setHovered] = React.useState<number | null>(null);
  const reduced = useReducedMotion();

  const source = Array.isArray(logos) ? logos.slice(0, 24) : LOGOS;
  const visible = source.slice(0, Math.round(clamp(count, 1, 24, source.length)));
  const rest = clamp(restOpacity, 0.1, 1, 0.5);
  const recede = clamp(recedeOpacity, 0, 1, 0.2);
  const blur = clamp(recedeBlur, 0, 8, 2);
  const scale = clamp(hoverScale, 1, 1.3, 1.06);

  const rise: Variants = reduced
    ? { hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4 } } }
    : {
        hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
        visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: SOFT },
      };

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <motion.div
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-80px" }}
        variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.05 } } }}
      >
        <div className="mx-auto max-w-2xl text-center">
          <motion.h2
            variants={rise}
            className="text-balance text-[28px] font-semibold leading-[1.1] tracking-[-0.03em] text-[#1d1d1f] dark:text-[#f5f5f7] sm:text-[40px]"
          >
            {title}
          </motion.h2>
          {subtitle ? (
            <motion.p variants={rise} className="mt-3 text-[17px] leading-[1.47] text-[#6e6e73] dark:text-[#a1a1a6]">
              {subtitle}
            </motion.p>
          ) : null}
        </div>

        <ul
          onMouseLeave={() => setHovered(null)}
          className="mx-auto mt-12 grid max-w-4xl grid-cols-2 place-items-center gap-x-6 gap-y-10 text-[#1d1d1f] dark:text-[#f5f5f7] sm:mt-14 sm:grid-cols-3 sm:gap-x-10 md:grid-cols-4 md:gap-y-12"
        >
          {visible.map((logo, i) => {
            const state = hovered === null ? "rest" : hovered === i ? "focus" : "recede";
            return (
              <motion.li key={`${i}-${logo.name}`} variants={rise}>
                <motion.div
                  onHoverStart={() => setHovered(i)}
                  animate={state}
                  initial={false}
                  variants={{
                    rest: { opacity: rest, scale: 1, filter: "blur(0px)" },
                    focus: { opacity: 1, scale: reduced ? 1 : scale, filter: "blur(0px)" },
                    recede: { opacity: recede, scale: reduced ? 1 : 0.97, filter: reduced ? "blur(0px)" : `blur(${blur}px)` },
                  }}
                  transition={SPRING}
                  className="flex cursor-default items-center"
                >
                  <LogoLockup logo={logo} className="text-[17px] sm:text-[20px]" />
                </motion.div>
              </motion.li>
            );
          })}
        </ul>
      </motion.div>
    </section>
  );
}

"use client";
// Infinite Marquee: two rows of monochrome marks drift in opposite directions. The edges fade
// out with a mask rather than a painted gradient, so the band sits on any background.

import * as React from "react";
import Marquee from "react-fast-marquee";
import { motion, useReducedMotion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup, type Logo } from "./logos";

const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

const EDGE_MASK = "linear-gradient(to right, transparent, black 12%, black 88%, transparent)";

export type LogoCloudMarqueeProps = {
  /** Small grey label above the headline. Empty string hides it. */
  eyebrow?: string;
  /** Headline above the band. */
  title?: string;
  /** Drift speed in px per second (5–200). */
  speed?: number;
  /** One row, or two rows drifting in opposite directions (the list is split in half). */
  rows?: number;
  /** Pause a row while the pointer is over it. */
  pauseOnHover?: boolean;
  /** Fade the band out at both edges with a mask. */
  fadeEdges?: boolean;
  /** Marks in the band (up to 24). Defaults to the twelve placeholder lockups. */
  logos?: Logo[];
  className?: string;
};

function clamp(value: number | undefined, min: number, max: number, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

function LogoItem({ logo }: { logo: Logo }) {
  return (
    <div className="mx-7 flex items-center text-[#1d1d1f]/50 transition-colors duration-300 ease-out hover:text-[#1d1d1f] dark:text-[#f5f5f7]/50 dark:hover:text-[#f5f5f7] sm:mx-10">
      <LogoLockup logo={logo} className="text-[17px] sm:text-[20px]" />
    </div>
  );
}

export default function LogoCloudMarquee({
  eyebrow = "Customers",
  title = "Running in production at 2,400 teams, from two-person studios to public companies.",
  speed = 34,
  rows = 2,
  pauseOnHover = true,
  fadeEdges = true,
  logos = LOGOS,
  className,
}: LogoCloudMarqueeProps) {
  const reduced = useReducedMotion();
  const source = Array.isArray(logos) ? logos.slice(0, 24) : LOGOS;
  const rowSpeed = clamp(speed, 5, 200, 34);
  const twoRows = Math.round(clamp(rows, 1, 2, 2)) === 2 && source.length > 1;
  const half = Math.ceil(source.length / 2);
  const rowOne = twoRows ? source.slice(0, half) : source;
  const rowTwo = twoRows ? source.slice(half) : [];
  const rise: Variants = reduced
    ? { hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4 } } }
    : {
        hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
        visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: SOFT },
      };

  return (
    <section className={cn("w-full bg-white py-16 dark:bg-black sm:py-24", className)}>
      <motion.div
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-80px" }}
        variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.08 } } }}
      >
        <div className="mx-auto max-w-3xl px-4 text-center">
          {eyebrow ? (
            <motion.p variants={rise} className="text-[17px] font-semibold tracking-[-0.01em] text-[#6e6e73] dark:text-[#a1a1a6]">
              {eyebrow}
            </motion.p>
          ) : null}
          <motion.h2
            variants={rise}
            className={cn(
              eyebrow ? "mt-2" : null,
              "text-balance text-[28px] font-semibold leading-[1.1] tracking-[-0.03em] text-[#1d1d1f] dark:text-[#f5f5f7] sm:text-[40px]",
            )}
          >
            {title}
          </motion.h2>
        </div>

        <motion.div
          variants={rise}
          className="relative mt-12 overflow-hidden motion-reduce:[&_.rfm-marquee]:![animation-play-state:paused] sm:mt-14"
          style={fadeEdges ? { WebkitMaskImage: EDGE_MASK, maskImage: EDGE_MASK } : undefined}
        >
          <div className="flex flex-col gap-8 sm:gap-10">
            <Marquee speed={rowSpeed} gradient={false} pauseOnHover={pauseOnHover}>
              {[...rowOne, ...rowOne].map((logo, i) => (
                <LogoItem key={`${logo.name}-${i}`} logo={logo} />
              ))}
            </Marquee>

            {rowTwo.length > 0 ? (
              <Marquee speed={rowSpeed} direction="right" gradient={false} pauseOnHover={pauseOnHover}>
                {[...rowTwo, ...rowTwo].map((logo, i) => (
                  <LogoItem key={`${logo.name}-${i}`} logo={logo} />
                ))}
              </Marquee>
            ) : null}
          </div>
        </motion.div>
      </motion.div>
    </section>
  );
}

"use client";
// Single Row with Hover Lift: the most restrained variant. One row of monochrome marks settles in
// with a light stagger. Hovering a mark lifts it on a spring while the rest of the row recedes.

import * as React from "react";
import { motion, useReducedMotion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup, type Logo } from "./logos";

const STAGGER = 0.06;
const SPRING = { type: "spring" as const, stiffness: 420, damping: 30 };
const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

export type LogoCloudSingleRowProps = {
  /** Small grey line above the row. Empty string hides it. */
  title?: string;
  /** How many marks to show (1–12), taken from the start of `logos`. */
  count?: number;
  /** Opacity of every mark while nothing is hovered (0.1–1). */
  restOpacity?: number;
  /** Opacity of the other marks while one is hovered (0–1). */
  recedeOpacity?: number;
  /** How far the hovered mark lifts, in px (0–16). */
  lift?: number;
  /** Scale of the hovered mark (1–1.3). */
  hoverScale?: number;
  /** Marks to pick from. Defaults to the twelve placeholder lockups. */
  logos?: Logo[];
  className?: string;
};

type HoverLook = { rest: number; recede: number; lift: number; scale: number };

function clamp(value: number | undefined, min: number, max: number, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

function LogoItem({
  logo,
  rise,
  reduced,
  isHovered,
  anyHovered,
  onHoverStart,
  look,
}: {
  logo: Logo;
  rise: Variants;
  reduced: boolean;
  isHovered: boolean;
  anyHovered: boolean;
  onHoverStart: () => void;
  look: HoverLook;
}) {
  return (
    // Outer wrapper takes the entrance stagger; the inner one owns hover, so the two never fight
    <motion.li variants={rise}>
      <motion.div
        onHoverStart={onHoverStart}
        initial={false}
        animate={{
          opacity: anyHovered ? (isHovered ? 1 : look.recede) : look.rest,
          y: isHovered && !reduced ? -look.lift : 0,
          scale: isHovered && !reduced ? look.scale : 1,
        }}
        transition={SPRING}
        className="flex cursor-default items-center text-[#1d1d1f] dark:text-[#f5f5f7]"
      >
        <LogoLockup logo={logo} className="text-[16px] sm:text-[18px]" />
      </motion.div>
    </motion.li>
  );
}

export default function LogoCloudSingleRow({
  title = "Product teams at these companies plan their week with us.",
  count = 6,
  restOpacity = 0.55,
  recedeOpacity = 0.22,
  lift = 4,
  hoverScale = 1.06,
  logos = LOGOS,
  className,
}: LogoCloudSingleRowProps) {
  const [hovered, setHovered] = React.useState<number | null>(null);
  const reduced = !!useReducedMotion();

  const source = Array.isArray(logos) ? logos : LOGOS;
  const rowLogos = source.slice(0, Math.round(clamp(count, 1, 12, 6)));
  const look: HoverLook = {
    rest: clamp(restOpacity, 0.1, 1, 0.55),
    recede: clamp(recedeOpacity, 0, 1, 0.22),
    lift: clamp(lift, 0, 16, 4),
    scale: clamp(hoverScale, 1, 1.3, 1.06),
  };

  const rise: Variants = reduced
    ? { hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4 } } }
    : {
        hidden: { opacity: 0, y: 12, filter: "blur(6px)" },
        visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: SOFT },
      };

  return (
    <section className={cn("w-full bg-white px-4 py-14 dark:bg-black sm:py-20", className)}>
      <motion.div
        className="mx-auto max-w-5xl"
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-80px" }}
        variants={{ hidden: {}, visible: { transition: { staggerChildren: STAGGER } } }}
      >
        {title ? (
          <motion.h2
            variants={rise}
            className="text-center text-[15px] font-medium tracking-[-0.01em] text-[#6e6e73] dark:text-[#a1a1a6]"
          >
            {title}
          </motion.h2>
        ) : null}

        <ul
          onMouseLeave={() => setHovered(null)}
          className={cn(
            title ? "mt-9" : null,
            "grid grid-cols-2 place-items-center gap-x-6 gap-y-8 sm:flex sm:flex-wrap sm:justify-center sm:gap-x-12 sm:gap-y-8",
          )}
        >
          {rowLogos.map((logo, i) => (
            <LogoItem
              key={`${i}-${logo.name}`}
              logo={logo}
              rise={rise}
              reduced={reduced}
              isHovered={hovered === i}
              anyHovered={hovered !== null}
              onHoverStart={() => setHovered(i)}
              look={look}
            />
          ))}
        </ul>
      </motion.div>
    </section>
  );
}

"use client";
// Cursor Spotlight: monochrome marks sit dimmed on a hairline grid. A soft circle of light trails
// the cursor on a spring, revealing the full-strength layer underneath. Motion values drive the
// mask directly through useMotionTemplate, so moving the pointer never re-renders React.

import * as React from "react";
import {
  motion,
  useMotionTemplate,
  useMotionValue,
  useReducedMotion,
  useSpring,
  type Variants,
} from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup, type Logo } from "./logos";

const FOLLOW = { stiffness: 260, damping: 30, mass: 0.6 };
const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

export type LogoCloudSpotlightProps = {
  /** Headline above the panel. */
  title?: string;
  /** Line under the headline. Empty string hides it. */
  subtitle?: string;
  /** Radius of the circle of light in px (80–600). */
  spotlightRadius?: number;
  /** Opacity of the dimmed marks outside the light (0–1). Unset keeps the built-in 25% ink. */
  dimOpacity?: number;
  /** How many marks to show (1–24). Defaults to every logo passed. */
  count?: number;
  /** Marks in the grid. Defaults to the twelve placeholder lockups. */
  logos?: Logo[];
  className?: string;
};

function clamp(value: number | undefined, min: number, max: number, fallback: number) {
  return typeof value === "number" && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

function LogoGrid({ dim, logos, dimOpacity }: { dim: boolean; logos: Logo[]; dimOpacity?: number }) {
  // A custom dim level paints full ink and fades the lockup instead of using the 25% text colour
  const customDim = dim && dimOpacity !== undefined;
  return (
    <div
      aria-hidden={dim ? undefined : true}
      className="grid grid-cols-2 gap-px overflow-hidden rounded-[20px] bg-black/[0.06] dark:bg-white/[0.08] sm:grid-cols-3 md:grid-cols-4"
    >
      {logos.map((logo, i) => (
        <div
          key={`${i}-${logo.name}`}
          className={cn(
            "flex h-20 items-center justify-center bg-white px-3 dark:bg-[#1c1c1e] sm:h-24",
            dim && !customDim ? "text-[#1d1d1f]/25 dark:text-[#f5f5f7]/25" : "text-[#1d1d1f] dark:text-[#f5f5f7]",
          )}
        >
          {customDim ? (
            <span className="inline-flex" style={{ opacity: dimOpacity }}>
              <LogoLockup logo={logo} className="text-[15px] sm:text-[18px]" />
            </span>
          ) : (
            <LogoLockup logo={logo} className="text-[15px] sm:text-[18px]" />
          )}
        </div>
      ))}
    </div>
  );
}

export default function LogoCloudSpotlight({
  title = "Twelve partners, one integration standard.",
  subtitle = "Move across the grid to light up each partner.",
  spotlightRadius = 240,
  dimOpacity,
  count,
  logos = LOGOS,
  className,
}: LogoCloudSpotlightProps) {
  const reduced = useReducedMotion();
  const source = Array.isArray(logos) ? logos.slice(0, 24) : LOGOS;
  const visible = source.slice(0, Math.round(clamp(count, 1, 24, source.length)));
  const radius = clamp(spotlightRadius, 80, 600, 240);
  const dim = dimOpacity === undefined ? undefined : clamp(dimOpacity, 0, 1, 0.25);
  const mouseX = useMotionValue(-9999);
  const mouseY = useMotionValue(-9999);
  // the light trails the pointer instead of sticking to it
  const x = useSpring(mouseX, FOLLOW);
  const y = useSpring(mouseY, FOLLOW);

  const maskImage = useMotionTemplate`radial-gradient(circle ${radius}px at ${x}px ${y}px, black 0%, transparent 72%)`;

  const panel = React.useRef<HTMLDivElement>(null);

  function handleMouseMove(e: React.MouseEvent<HTMLDivElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    mouseX.set(e.clientX - rect.left);
    mouseY.set(e.clientY - rect.top);
  }

  // rest the light in the middle of the grid, so touch screens and keyboard users see it lit too
  const rest = React.useCallback(
    (instant: boolean) => {
      const el = panel.current;
      if (!el) return;
      const cx = el.clientWidth / 2;
      const cy = el.clientHeight / 2;
      mouseX.set(cx);
      mouseY.set(cy);
      if (instant) {
        x.jump(cx);
        y.jump(cy);
      }
    },
    [mouseX, mouseY, x, y],
  );

  React.useEffect(() => {
    // wait a frame: the masked layer subscribes to the motion values after this effect
    const id = requestAnimationFrame(() => rest(true));
    return () => cancelAnimationFrame(id);
  }, [rest]);

  const rise: Variants = reduced
    ? { hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4 } } }
    : {
        hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
        visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: SOFT },
      };

  return (
    <section className={cn("w-full bg-[#f5f5f7] px-4 py-16 dark:bg-black sm:py-24", className)}>
      <motion.div
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-80px" }}
        variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.08 } } }}
      >
        <div className="mx-auto max-w-2xl text-center">
          <motion.h2
            variants={rise}
            className="text-balance text-[28px] font-semibold leading-[1.1] tracking-[-0.03em] text-[#1d1d1f] dark:text-[#f5f5f7] sm:text-[40px]"
          >
            {title}
          </motion.h2>
          {subtitle ? (
            <motion.p variants={rise} className="mt-3 text-[17px] leading-[1.47] text-[#6e6e73] dark:text-[#a1a1a6]">
              {subtitle}
            </motion.p>
          ) : null}
        </div>

        <motion.div
          variants={rise}
          ref={panel}
          onMouseMove={handleMouseMove}
          onMouseLeave={() => rest(false)}
          className="relative mx-auto mt-12 max-w-4xl overflow-hidden rounded-[28px] bg-white p-2 shadow-[0_0_0_1px_rgba(0,0,0,.05),0_20px_40px_-24px_rgba(0,0,0,.25)] dark:bg-[#1c1c1e] dark:shadow-[0_0_0_1px_rgba(255,255,255,.08)] sm:mt-14"
        >
          {/* Base dim layer */}
          <LogoGrid dim logos={visible} dimOpacity={dim} />

          {/* Full-strength layer, masked to the trailing light */}
          <motion.div
            className="pointer-events-none absolute inset-0 p-2"
            style={{ WebkitMaskImage: maskImage, maskImage }}
          >
            <LogoGrid dim={false} logos={visible} />
          </motion.div>
        </motion.div>
      </motion.div>
    </section>
  );
}

"use client";
// Swap Animation: a fixed set of slots shows one page of marks at a time. Every `interval` ms the
// next page rolls in, slot by slot from left to right: the outgoing mark lifts away and blurs out
// while the incoming one rises into place on a spring. Pauses while off screen.

import * as React from "react";
import { AnimatePresence, motion, useInView, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup } from "./logos";

export type LogoEntry = {
  icon: React.ReactNode;
  name?: string;
  id?: string;
};

export type LogoCloudSwapProps = {
  logos?: LogoEntry[];
  title?: string;
  subtitle?: string;
  interval?: number;
  stagger?: number;
  /** How many marks are on screen at once. Defaults to 6. */
  slots?: number;
  className?: string;
};

const SPRING = { type: "spring" as const, stiffness: 400, damping: 32 };
const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

const DEFAULT_LOGOS: LogoEntry[] = LOGOS.map((l) => ({
  icon: <LogoLockup logo={l} className="text-[17px] sm:text-[19px]" />,
  id: l.name,
}));

function Slot({
  logo,
  page,
  delay,
  reduced,
}: {
  logo: LogoEntry;
  page: number;
  delay: number;
  reduced: boolean;
}) {
  const motionIn = reduced ? { opacity: 0 } : { opacity: 0, y: "100%", filter: "blur(6px)" };
  const motionOut = reduced ? { opacity: 0 } : { opacity: 0, y: "-100%", filter: "blur(6px)" };

  return (
    <div className="relative flex h-16 w-full items-center justify-center overflow-hidden opacity-55 transition-opacity duration-300 ease-out hover:opacity-100">
      <AnimatePresence mode="popLayout" initial={false}>
        <motion.div
          key={`${page}-${logo.id ?? logo.name ?? ""}`}
          role={logo.name ? "img" : undefined}
          aria-label={logo.name}
          initial={motionIn}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)", transition: { ...SPRING, delay } }}
          exit={{ ...motionOut, transition: { ...SPRING, delay } }}
          className="flex cursor-default flex-col items-center gap-1.5 text-[#1d1d1f] dark:text-[#f5f5f7]"
        >
          <span className="flex h-8 min-w-8 items-center justify-center">{logo.icon}</span>
          {logo.name ? (
            <span className="select-none whitespace-nowrap text-[12px] font-medium">{logo.name}</span>
          ) : null}
        </motion.div>
      </AnimatePresence>
    </div>
  );
}

export default function LogoCloudSwap({
  logos = DEFAULT_LOGOS,
  title = "Chosen by teams who sweat the details",
  subtitle = "Each of these replaced three tools with one.",
  interval = 3200,
  stagger = 0.08,
  slots = 6,
  className,
}: LogoCloudSwapProps) {
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const reduced = !!useReducedMotion();
  const [page, setPage] = React.useState(0);

  const slotCount = Math.max(1, Math.min(slots, logos.length));
  const pages = Math.max(1, Math.ceil(logos.length / slotCount));

  React.useEffect(() => {
    if (!inView || pages < 2) return;
    const id = window.setInterval(() => setPage((p) => p + 1), interval);
    return () => window.clearInterval(id);
  }, [inView, interval, pages]);

  const pageIndex = page % pages;

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <motion.div
        className="mx-auto max-w-2xl text-center"
        initial={reduced ? { opacity: 0 } : { opacity: 0, y: 16, filter: "blur(6px)" }}
        whileInView={{ opacity: 1, y: 0, filter: "blur(0px)" }}
        viewport={{ once: true, margin: "-80px" }}
        transition={SOFT}
      >
        <h2 className="text-balance text-[28px] font-semibold leading-[1.1] tracking-[-0.03em] text-[#1d1d1f] dark:text-[#f5f5f7] sm:text-[40px]">
          {title}
        </h2>
        {subtitle ? (
          <p className="mt-3 text-[17px] leading-[1.47] text-[#6e6e73] dark:text-[#a1a1a6]">{subtitle}</p>
        ) : null}
      </motion.div>

      <div
        ref={ref}
        className={cn(
          "mx-auto mt-12 grid max-w-5xl grid-cols-2 gap-x-4 gap-y-4 sm:mt-14 sm:grid-cols-3 sm:gap-x-8",
          slotCount >= 6 && "lg:grid-cols-6",
        )}
      >
        {Array.from({ length: slotCount }, (_, i) => {
          const logo = logos[(pageIndex * slotCount + i) % logos.length];
          return <Slot key={i} logo={logo} page={page} delay={i * stagger} reduced={reduced} />;
        })}
      </div>
    </section>
  );
}

"use client";
// Periodic Blur-Flip: monochrome marks hold their places in a quiet grid. Every `interval` ms each
// mark rolls over in place, one after another: the face tips back and blurs away while a fresh copy
// springs up from below. Transforms and opacity only, so nothing around it shifts.

import * as React from "react";
import { AnimatePresence, motion, useInView, useReducedMotion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";
import { LOGOS, LogoLockup } from "./logos";

// ─── Types ────────────────────────────────────────────────────────────────────

export type LogoEntry = {
  icon: React.ReactNode;
  name?: string;
  id?: string;
};

export type LogosBlurFlipProps = {
  logos?: LogoEntry[];
  title?: string;
  subtitle?: string;
  interval?: number;
  className?: string;
};

// ─── Animation config ─────────────────────────────────────────────────────────

const STAGGER = 0.05;
const FLIP = { type: "spring" as const, stiffness: 300, damping: 26 };
const SOFT = { type: "spring" as const, stiffness: 240, damping: 30 };

// ─── Default logos ────────────────────────────────────────────────────────────

const DEFAULT_LOGOS: LogoEntry[] = LOGOS.map((l) => ({
  icon: <LogoLockup logo={l} className="text-[17px] sm:text-[19px]" />,
  id: l.name,
}));

// ─── Logo Item ────────────────────────────────────────────────────────────────

function LogoFace({ logo }: { logo: LogoEntry }) {
  return (
    <>
      <span className="flex h-9 min-w-9 items-center justify-center sm:h-10 sm:min-w-10">{logo.icon}</span>
      {logo.name ? (
        <span className="select-none whitespace-nowrap text-[12px] font-medium">{logo.name}</span>
      ) : null}
    </>
  );
}

function LogoItem({
  logo,
  index,
  cycle,
  reduced,
  rise,
}: {
  logo: LogoEntry;
  index: number;
  cycle: number;
  reduced: boolean;
  rise: Variants;
}) {
  const delay = index * STAGGER;
  return (
    // the list item takes the entrance; the inner wrapper owns the resting opacity and hover
    <motion.li variants={rise} role={logo.name ? "img" : undefined} aria-label={logo.name} className="w-full">
      <div className="relative flex h-16 items-center justify-center text-[#1d1d1f] opacity-55 transition-opacity duration-300 ease-out [perspective:700px] hover:opacity-100 dark:text-[#f5f5f7]">
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={cycle}
            className="flex origin-center flex-col items-center gap-1.5"
            initial={reduced ? { opacity: 0 } : { opacity: 0, rotateX: 80, y: "45%", filter: "blur(8px)" }}
            animate={{ opacity: 1, rotateX: 0, y: 0, filter: "blur(0px)", transition: { ...FLIP, delay } }}
            exit={
              reduced
                ? { opacity: 0, transition: { duration: 0.2, delay } }
                : { opacity: 0, rotateX: -80, y: "-45%", filter: "blur(8px)", transition: { ...FLIP, delay } }
            }
          >
            <LogoFace logo={logo} />
          </motion.span>
        </AnimatePresence>
      </div>
    </motion.li>
  );
}

// ─── Main component ───────────────────────────────────────────────────────────

export default function LogosBlurFlip({
  logos = DEFAULT_LOGOS,
  title = "Used by teams that ship every week",
  subtitle = "From two-person studios to platform teams of four hundred.",
  interval = 2600,
  className,
}: LogosBlurFlipProps) {
  const ref = React.useRef<HTMLUListElement>(null);
  const inView = useInView(ref, { margin: "-80px" });
  const reduced = !!useReducedMotion();
  const [cycle, setCycle] = React.useState(0);

  React.useEffect(() => {
    if (!inView || reduced) return;
    const id = window.setInterval(() => setCycle((c) => c + 1), interval);
    return () => window.clearInterval(id);
  }, [inView, interval, reduced]);

  const rise: Variants = reduced
    ? { hidden: { opacity: 0 }, visible: { opacity: 1, transition: { duration: 0.4 } } }
    : {
        hidden: { opacity: 0, y: 16, filter: "blur(6px)" },
        visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: SOFT },
      };

  return (
    <section className={cn("w-full bg-white px-4 py-16 dark:bg-black sm:py-24", className)}>
      <motion.div
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: "-80px" }}
        variants={{ hidden: {}, visible: { transition: { staggerChildren: 0.04 } } }}
      >
        <div className="mx-auto max-w-2xl text-center">
          <motion.h2
            variants={rise}
            className="text-balance text-[28px] font-semibold leading-[1.1] tracking-[-0.03em] text-[#1d1d1f] dark:text-[#f5f5f7] sm:text-[40px]"
          >
            {title}
          </motion.h2>
          {subtitle ? (
            <motion.p variants={rise} className="mt-3 text-[17px] leading-[1.47] text-[#6e6e73] dark:text-[#a1a1a6]">
              {subtitle}
            </motion.p>
          ) : null}
        </div>

        <ul
          ref={ref}
          className="mx-auto mt-12 grid max-w-5xl grid-cols-2 place-items-center gap-x-4 gap-y-4 sm:mt-14 sm:grid-cols-3 sm:gap-x-10 lg:grid-cols-6"
        >
          {logos.map((logo, i) => (
            <LogoItem key={logo.id ?? i} logo={logo} index={i} cycle={cycle} reduced={reduced} rise={rise} />
          ))}
        </ul>
      </motion.div>
    </section>
  );
}

